// Verifica .

#if UNITY_EDITOR
using System;using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace HorrorGame.Tests
{
 [Category("SecretaryEvidence")]
 public sealed class SecretaryEvidenceTests
 {
  const string Folder="Assets/HorrorGameplay/Data/BeforeDemolition/School/";
  [Test] public void LunchboxKeepsItsIdModelAndFiveImageSlots()
  {var item=AssetDatabase.LoadAssetAtPath<InspectionItemData>(Folder+"Lunchbox.asset");Assert.That(item.itemId,Is.EqualTo("bd.lunchbox"));Assert.That(AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(item.model)),Is.EqualTo("fcce3d16d988dc049bf4bd24319be304"));Assert.That(item.pages.Length,Is.EqualTo(3));Assert.That(item.pages.All(p=>p.image&&p.image.width==2048&&p.image.height==1536),Is.True);Assert.That(item.pages.Count(p=>p.currentDate),Is.EqualTo(1));Assert.That(item.pages[2].label,Is.EqualTo("26/10/2026"));Assert.That(item.model.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="Merenda de 2006"),Is.False);}
  [Test] public void OldSavedNotesMigrateOnlyTheirWordsAndRetainOwnershipAndHistory()
  {var old=new SaveData{inventory=new System.Collections.Generic.List<InventoryItem>{new InventoryItem{id="bd.cups",title="Quatro copos gelados",text="Quatro copos de suco. Ainda estão gelados. Um tem pequenas marcas de dentes na borda. Ninguém devia ter servido isso hoje.",inspectionId="bd.cups",inspectionCount=3,inspectionSeen=true,note=true},new InventoryItem{id="bd.library.key",title="Chave",inspectionId="bd.library.key"}}};string frozen=JsonUtility.ToJson(old);var copy=JsonUtility.FromJson<SaveData>(frozen);var go=new GameObject("Discarded inventory test");try{var inv=go.AddComponent<Inventory>();inv.Restore(copy.inventory);Assert.That(inv.Contains("bd.library.key"),Is.True);var clue=inv.items[0];Assert.That(clue.title,Is.EqualTo("Pegadas pequenas na poeira"));Assert.That(clue.text,Does.Contain("pegadas pequenas").And.Not.Contain("suco"));Assert.That(clue.inspectionId,Is.EqualTo("bd.cups"));Assert.That(clue.inspectionCount,Is.EqualTo(3));Assert.That(clue.inspectionSeen&&clue.note,Is.True);Assert.That(JsonUtility.ToJson(old),Is.EqualTo(frozen));}finally{UnityEngine.Object.DestroyImmediate(go);}}
  [Test] public void ArchivedAndCustomNotesDoNotMigrateByCoincidentalWording()
  {var go=new GameObject("Other campaign copy");try{var inventory=go.AddComponent<Inventory>();var old=new InventoryItem{id="archived.note",title="Quatro copos gelados",text="A merenda estava quente."};inventory.Restore(new System.Collections.Generic.List<InventoryItem>{old});Assert.That(old.title,Is.EqualTo("Quatro copos gelados"));Assert.That(old.text,Is.EqualTo("A merenda estava quente."));}finally{UnityEngine.Object.DestroyImmediate(go);}}
  [TestCase(null)][TestCase("")][TestCase("Uma chave na gaveta.")] public void UnrelatedAndMissingNotesRemainUnchanged(string text)=>Assert.That(SecretaryEvidenceText.Refresh(text),Is.EqualTo(text));
  [Test] public void CanonicalAndCompatibilityEmailAssetsAgreeWithoutChangingMetadata()
  {var current=AssetDatabase.LoadAssetAtPath<EmailCatalog>("Assets/HorrorGameplay/Data/BeforeDemolition/BeforeDemolitionOfficeEmails.asset");var legacy=AssetDatabase.LoadAssetAtPath<EmailCatalog>("Assets/HorrorGameplay/Email/BeforeDemolitionEmails.asset");var defaults=EmailCatalog.BeforeDemolitionContent();foreach(string id in new[]{"email.02","email.03"}){var a=current.Find(id);Assert.That(a.PlainText,Is.EqualTo(defaults.Single(x=>x.id==id).PlainText));Assert.That(legacy.Find(id).PlainText,Is.EqualTo(a.PlainText));Assert.That(a.PlainText,SystemsForbidden.NotOldFood());}Assert.That(current.Find("email.02").date,Is.EqualTo("09/04/2007"));Assert.That(current.Find("email.02").subject,Is.EqualTo("RE: Alunos da 7B"));Assert.That(current.Find("email.02").time,Is.Empty);Assert.That(current.Find("email.03").time,Is.EqualTo("03:07"));Assert.That(current.Find("email.03").initiallyDelivered,Is.True);}
  [Test] public void NativeSceneHasOnlyTracksAStoppedClockAndNoGlassResponder()
  {var scene=EditorSceneManager.OpenPreviewScene("Assets/SchoolCEEP/Scenes/SchoolCEEP.unity");try{var all=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Transform>(true)).ToArray();var e=all.Select(t=>t.GetComponent<SecretaryEvidence>()).Single(x=>x);Assert.That(e.footprints.Length,Is.EqualTo(4));Assert.That(e.footprints.All(r=>r&&r.sharedMaterial),Is.True);Assert.That(e.keyEcho.enabled,Is.False);Assert.That(e.clock.name,Does.Contain("03:07"));Assert.That(all.Any(t=>t.name=="Merenda de 2006"||t.name=="Quatro copos gelados"),Is.False);Assert.That(all.Select(t=>t.GetComponent<WhistleResponder>()).Any(r=>r&&r.responderId=="whistle.school.cups"),Is.False);foreach(var hand in e.clock.GetComponentsInChildren<MeshFilter>(true).Where(h=>h.name.Contains("minute_hand")||h.name.Contains("hours_hand"))){Vector3 pivot=e.clockFaceCenter;var vertices=hand.sharedMesh.vertices.Select(v=>e.clock.InverseTransformPoint(hand.transform.TransformPoint(v))).ToArray();float max=vertices.Max(v=>new Vector2(v.x-pivot.x,v.y-pivot.y).sqrMagnitude);var ends=vertices.Where(v=>new Vector2(v.x-pivot.x,v.y-pivot.y).sqrMagnitude>=max*.95f).ToArray();var tip=ends.Aggregate(Vector3.zero,(a,v)=>a+v)/ends.Length;float actual=Mathf.Atan2(tip.x-pivot.x,tip.y-pivot.y)*Mathf.Rad2Deg;Assert.That(Mathf.Abs(Mathf.DeltaAngle(actual,hand.name.Contains("minute")?42:93.5f)),Is.LessThan(.1f),hand.name);}}finally{EditorSceneManager.ClosePreviewScene(scene);}}
  [Test] public void SixNewContextLinesHaveUniqueTriggersAndNoSyntheticVoice()
  {var c=AssetDatabase.LoadAssetAtPath<WhistleDialogueCatalog>("Assets/HorrorGameplay/Data/Whistle/WhistleDialogue.asset");var lines=c.lines.Where(l=>l.id.StartsWith("secretary.")).ToArray();Assert.That(lines.Length,Is.EqualTo(6));Assert.That(lines.Select(l=>l.trigger).Distinct().Count(),Is.EqualTo(6));Assert.That(lines.All(l=>!l.voice),Is.True);}
 }
 static class SystemsForbidden { public static NUnit.Framework.Constraints.Constraint NotOldFood()=>Does.Not.Match(@"(?i)\bcopos?\b|\bsuco\b|marca[s]? de dente|merenda.*quente"); }
}
#endif
